<?php
namespace App\Filament\Resources\VoiceEventResource\Pages; use App\Filament\Resources\VoiceEventResource; use App\Models\VoiceEvent; use Filament\Actions; use Filament\Notifications\Notification; use Filament\Resources\Pages\ListRecords;
class ListVoiceEvents extends ListRecords {protected static string $resource=VoiceEventResource::class; public function mount(): void {parent::mount(); VoiceEvent::pruneExpired();} protected function getHeaderActions(): array {return [Actions\Action::make('pruneExpired')->label('Retirer les logs expirés')->icon('heroicon-o-clock')->color('gray')->action(function(): void {$deleted=VoiceEvent::pruneExpired();Notification::make()->title($deleted.' log(s) expiré(s) supprimé(s)')->success()->send();}),Actions\Action::make('clearLogs')->label('Vider les logs')->icon('heroicon-o-trash')->color('danger')->requiresConfirmation()->modalHeading('Vider tous les logs vocaux ?')->modalDescription('Cette action supprime définitivement tous les logs d’activité vocale.')->action(function(): void {$deleted=VoiceEvent::query()->delete();Notification::make()->title($deleted.' log(s) supprimé(s)')->success()->send();})];}}
